let embeddedRule0379: RuleEntry = RuleEntry(
    id: "cprh_ch05_toning_down_the_cleric",
    book: "CPrH",
    chapterNumber: 5,
    chapterTitle: "Role-Playing",
    breadcrumbs: "The Complete Priest's Handbook > Chapter 5: Role-Playing > Toning Down the Cleric",
    topic: "Toning Down the Cleric",
    ruleType: "core_rule",
    summary: "The cleric class is a very powerful one. He has access to sixteen Spheres of Influence (more than *any* other priest-class), good armor, and fair weapons.",
    content: "The cleric class is a very powerful one. He has access to sixteen Spheres of Influence (more than *any* other priest-class), good armor, and fair weapons. It's been a sign of the cleric's advantages that he is the preferred character class of many, many campaigns.\n\nIf this ultra-efficient character is too powerful in your own campaign, you might prefer to alter him. If you want to do this, tell all the cleric players well ahead of time and give them the option to convert their clerics to priests of specific mythoi provided in the **Sample Priesthoods** chapter.\n\nThen, establish the following rules about the Cleric class:\n\n1. Keep his weapon and armor limitations exactly as they are.\n1. Establish that the Cleric has Major Access to only three spheres (one must be All; the other two are player's choice) and Minor Access to two spheres (player's choice). The player must choose his four sphere options when the Cleric is first created (or converted); it may not be changed afterwards. Each Cleric may choose a different set of spheres.\n\nNaturally, you should only do this if you personally feel that the cleric class is too powerful in your campaign. If you don't, don't change him.",
    tables: [],
    relatedRuleIds: ["cprh_ch03_sample_priesthoods", "cprh_ch02_spheres_of_influence"],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["cleric", "down", "priesthood", "sphere", "toning", "toning down the cleric"]
)

let embeddedRule0380: RuleEntry = RuleEntry(
    id: "cprh_ch05_when_gods_bestow_spells",
    book: "CPrH",
    chapterNumber: 5,
    chapterTitle: "Role-Playing",
    breadcrumbs: "The Complete Priest's Handbook > Chapter 5: Role-Playing > When Gods Bestow Spells",
    topic: "When Gods Bestow Spells",
    ruleType: "core_rule",
    summary: "Another effect of the fact that priests are servants of their gods is this: The god doesn't have to give his priest the spells the priest wants.",
    content: "Another effect of the fact that priests are servants of their gods is this: The god doesn't have to give his priest the spells the priest wants.\n\nIn most situations, when the priest prays for his spells, he gets the ones he desires. But if the god and DM wish, he could get different spells on some occasions.\n\nThere are two usual causes for this to happen:\n\nIf the god is displeased with the priest for some minor infraction, he might give the priest spells which dictate the priests' actions for the day. A fighting-priest might emerge from his meditation with only healing spells on hand, for instance, a clear sign that the god wants him to act in a supporting role today.\n\nOr, if the god knows of a specific opponent that the priest will be fighting today, he might give the priest spells appropriate to defeating that enemy.\n\nIn neither case will the god send a telegram explaining why he's done what he's done. The priest has to accept what the god hands him that day, and has to do so without knowing why.",
    tables: [],
    relatedRuleIds: [],
    relatedSpells: [],
    relatedMagicItems: [],
    searchKeywords: ["bestow", "gods", "spells", "when", "when gods bestow spells"]
)

